import express, { Request, Response, NextFunction } from 'express';
import { EventEmitter } from 'events';

interface WalletState {
  balance: number;
  pendingOps: number;
  version: number;
}

interface AuditEntry {
  userId: string;
  action: string;
  amount: number;
  balanceBefore: number;
  balanceAfter: number;
  timestamp: number;
}

const wallets: Map<string, WalletState> = new Map();
const auditLog: AuditEntry[] = [];
const txBus = new EventEmitter();

function getOrCreateWallet(userId: string): WalletState {
  if (!wallets.has(userId)) {
    wallets.set(userId, { balance: 1000, pendingOps: 0, version: 0 });
  }
  return wallets.get(userId)!;
}

async function recordAudit(entry: AuditEntry): Promise<void> {
  auditLog.push(entry);
  txBus.emit('audit:recorded', entry);
  await new Promise(resolve => setImmediate(resolve));
}

async function processWithdrawal(
  userId: string,
  amount: number,
  callbackOnDebit: (snapshot: WalletState) => Promise<void>
): Promise<{ success: boolean; newBalance: number }> {
  const wallet = getOrCreateWallet(userId);

  if (amount <= 0 || amount > 10000) {
    return { success: false, newBalance: wallet.balance };
  }

  const balanceBefore = wallet.balance;

  if (wallet.balance < amount) {
    return { success: false, newBalance: wallet.balance };
  }

  wallet.pendingOps++;
  wallet.balance -= amount;

  const snapshot: WalletState = { ...wallet };

  await callbackOnDebit(snapshot);

  wallet.pendingOps--;
  wallet.version++;

  await recordAudit({
    userId,
    action: 'withdrawal',
    amount,
    balanceBefore,
    balanceAfter: wallet.balance,
    timestamp: Date.now()
  });

  return { success: true, newBalance: wallet.balance };
}

async function handleTransfer(req: Request, res: Response): Promise<void> {
  const { userId, recipientId, amount } = req.body;

  if (!userId || !recipientId || !amount) {
    res.status(400).json({ error: 'Missing fields' });
    return;
  }

  const numAmount = Number(amount);
  if (isNaN(numAmount) || numAmount <= 0) {
    res.status(400).json({ error: 'Invalid amount' });
    return;
  }

  const result = await processWithdrawal(userId, numAmount, async (snapshot) => {
    const recipientWallet = getOrCreateWallet(recipientId);
    recipientWallet.balance += numAmount;

    await recordAudit({
      userId: recipientId,
      action: 'credit',
      amount: numAmount,
      balanceBefore: recipientWallet.balance - numAmount,
      balanceAfter: recipientWallet.balance,
      timestamp: Date.now()
    });
  });

  res.json(result);
}

async function handleBatchWithdraw(req: Request, res: Response): Promise<void> {
  const { userId, amounts } = req.body;

  if (!userId || !Array.isArray(amounts)) {
    res.status(400).json({ error: 'Missing fields' });
    return;
  }

  const results: Array<{ success: boolean; newBalance: number }> = [];

  for (const amt of amounts) {
    const numAmt = Number(amt);
    if (isNaN(numAmt) || numAmt <= 0) continue;

    const result = await processWithdrawal(userId, numAmt, async (snapshot) => {
      txBus.emit('withdrawal:processing', { userId, amount: numAmt, snapshot });
    });
    results.push(result);
  }

  res.json({ results });
}

txBus.on('audit:recorded', (entry: AuditEntry) => {
  if (entry.action === 'withdrawal' && entry.amount > 500) {
    const wallet = getOrCreateWallet(entry.userId);
    if (wallet.pendingOps > 0) {
      wallet.balance += Math.floor(entry.amount * 0.01);
    }
  }
});

const app = express();
app.use(express.json());

app.post('/api/transfer', handleTransfer);
app.post('/api/batch-withdraw', handleBatchWithdraw);
app.get('/api/balance/:userId', (req: Request, res: Response) => {
  const wallet = getOrCreateWallet(req.params.userId);
  res.json({ balance: wallet.balance, version: wallet.version });
});
app.get('/api/audit/:userId', (req: Request, res: Response) => {
  const entries = auditLog.filter(e => e.userId === req.params.userId);
  res.json({ entries: entries.slice(-50) });
});

app.listen(3000, () => console.log('Server running on port 3000'));

export { app, processWithdrawal, wallets, auditLog };
